<template><div class="page-view"><div class="page-header"><div><h2>城市管理</h2><p>维护可扩展的城市上下文入口。</p></div><el-button type="primary" @click="openCreate">新增城市</el-button></div><div class="page-card"><el-input v-model="keyword" placeholder="搜索城市名称或编码" clearable @keyup.enter="load" /><el-table :data="rows" v-loading="loading" style="margin-top:16px"><el-table-column prop="cityName" label="城市"/><el-table-column prop="cityCode" label="编码"/><el-table-column prop="province" label="省份"/><el-table-column prop="status" label="状态"><template #default="{row}">{{ row.status === 1 ? '启用' : '停用' }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="openEdit(row)">编辑</el-button><el-button link type="danger" @click="disable(row)">停用</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="城市" width="520px"><el-form :model="form"><el-form-item label="城市编码"><el-input v-model="form.cityCode"/></el-form-item><el-form-item label="城市名称"><el-input v-model="form.cityName"/></el-form-item><el-form-item label="省份"><el-input v-model="form.province"/></el-form-item><el-form-item label="宣传语"><el-input v-model="form.slogan"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { createCity, disableCity, pageCities, updateCity } from '../../api/city'; import type { CityVO } from '../../types';
const rows=ref<CityVO[]>([]), loading=ref(false), keyword=ref(''), visible=ref(false); const form=reactive<Partial<CityVO>>({});
async function load(){loading.value=true;try{rows.value=await pageCities(keyword.value)}finally{loading.value=false}} function openCreate(){Object.assign(form,{cityCode:'',cityName:'',province:'',slogan:'',country:'中国',status:1,sortOrder:0});visible.value=true} function openEdit(row:CityVO){Object.assign(form,row);visible.value=true} async function save(){if(!form.cityCode||!form.cityName)return ElMessage.warning('请填写城市编码和名称'); if(form.id) await updateCity(form as CityVO); else await createCity(form); visible.value=false; await load()} async function disable(row:CityVO){await ElMessageBox.confirm(`停用 ${row.cityName}？`);await disableCity(row.id);await load()} onMounted(load)</script>
